import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.RemoveObjective{ObjectiveName: "kills"}
KILLS = bytes.fromhex("056b696c6c73")

# generated by gophertunnel b8bd735:
# &packet.RemoveObjective{ObjectiveName: ""}
EMPTY = bytes.fromhex("00")

# generated by gophertunnel b8bd735:
# &packet.RemoveObjective{ObjectiveName: strings.Repeat("o", 200)}
LONG = bytes.fromhex("c801") + bytes.fromhex("6f") * 200

GOLDENS = [
    pytest.param(v2225.RemoveObjectivePacket(objective_name="kills"), KILLS, id="kills"),
    pytest.param(v2225.RemoveObjectivePacket(), EMPTY, id="empty-name-is-a-bare-length-byte"),
    pytest.param(
        v2225.RemoveObjectivePacket(objective_name="o" * 200),
        LONG,
        id="200-byte-name-takes-a-two-byte-length",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_remove_objective_is_packet_106(version):
    assert version.PACKETS[106] is version.RemoveObjectivePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_remove_objective_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_remove_objective_decodes_from_its_golden(packet, golden):
    assert v2225.RemoveObjectivePacket.from_bytes(golden) == packet
